/**
 * EzyCore Commerce Components
 * Shared utilities + Alpine.js data components
 */

// ============================================
// SHARED UTILITIES
// ============================================

window.formatPrice = function (num) {
    return "Rp " + Number(num).toLocaleString("id-ID");
};

window.extractImages = function (meta) {
    return (meta.images && meta.images.length > 0)
        ? meta.images
        : (meta.image ? [meta.image] : [(meta.title || meta.name || '?').substring(0, 2).toUpperCase()]);
};

window.parseEzyMeta = function (content) {
    var parser = new DOMParser();
    var doc = parser.parseFromString(content, "text/html");
    var el = doc.querySelector(".ezy-meta");
    if (!el) return null;
    var raw = el.getAttribute("data-meta") || "{}";
    try {
        return JSON.parse(raw.replace(/&apos;/g, "\x27").replace(/'/g, "'"));
    } catch (e) {
        return null;
    }
};

// Shared product cache - avoid redundant fetches
window._productCache = window._productCache || {
    data: null,
    fetchedAt: 0,
    ttl: 5 * 60 * 1000 // 5 minutes
};

window.fetchProducts = async function () {
    var cache = window._productCache;
    var now = Date.now();

    // Return cached data if still valid
    if (cache.data && (now - cache.fetchedAt) < cache.ttl) {
        return cache.data;
    }

    try {
        var res = await fetch("/feeds/posts/default/-/product?alt=json&maxResults=500");
        if (!res.ok) throw new Error("Fetch failed");
        var json = await res.json();

        if (json.feed && json.feed.entry) {
            var parsed = [];
            for (var idx = 0; idx < json.feed.entry.length; idx++) {
                try {
                    var entry = json.feed.entry[idx];
                    var content = entry.content && entry.content.$t ? entry.content.$t : "";
                    var meta = window.parseEzyMeta(content);
                    if (!meta || meta._type !== "product") continue;

                    var alternateLink = "";
                    if (entry.link) {
                        for (var k = 0; k < entry.link.length; k++) {
                            if (entry.link[k].rel === "alternate") {
                                alternateLink = entry.link[k].href;
                                break;
                            }
                        }
                    }

                    parsed.push({
                        id: meta.id || "",
                        name: meta.name || (entry.title ? entry.title.$t : "") || "",
                        slug: (function() {
                            if (alternateLink) {
                                var parts = alternateLink.replace(/\/$/, "").split("/");
                                var urlSlug = parts[parts.length - 1].replace(/\.html$/, '');
                                if (urlSlug) return urlSlug;
                            }
                            return meta.slug || "";
                        })(),
                        postUrl: alternateLink,
                        price: Number(meta.price) || 0,
                        category: meta.category || "",
                        image: meta.image || "",
                        images: meta.images || [],
                        stock: Number(meta.stock) || 0,
                        compareatprice: Number(meta.compareatprice) || 0,
                        description: meta.description || "",
                        sku: meta.sku || "",
                        weight: Number(meta.weight) || 0,
                        weightunit: meta.weightunit || "gram",
                        publishedat: meta.publishedat || "",
                        _type: "product"
                    });
                } catch (e) { /* skip */ }
            }
            cache.data = parsed;
            cache.fetchedAt = now;
            return parsed;
        }
    } catch (e) {
        console.warn("fetchProducts failed:", e);
    }
    return [];
};

// Shared figure cache
window._figureCache = window._figureCache || { data: null, fetchedAt: 0, ttl: 5 * 60 * 1000 };

window.fetchFigures = async function () {
    var cache = window._figureCache;
    var now = Date.now();
    if (cache.data && (now - cache.fetchedAt) < cache.ttl) return cache.data;

    try {
        var res = await fetch("/feeds/posts/default/-/Figure?alt=json&max-results=500");
        if (!res.ok) throw new Error("Fetch failed");
        var json = await res.json();

        if (json.feed && json.feed.entry) {
            var parsed = [];
            for (var idx = 0; idx < json.feed.entry.length; idx++) {
                try {
                    var entry = json.feed.entry[idx];
                    var content = entry.content && entry.content.$t ? entry.content.$t : "";
                    var meta = window.parseEzyMeta(content);
                    if (!meta || meta._type !== "figure") {
                        continue;
                    }

                    var alternateLink = "";
                    if (entry.link) {
                        for (var k = 0; k < entry.link.length; k++) {
                            if (entry.link[k].rel === "alternate") {
                                alternateLink = entry.link[k].href;
                                break;
                            }
                        }
                    }

                    var slug = "";
                    if (alternateLink) {
                        var parts = alternateLink.replace(/\/$/, "").split("/");
                        slug = parts[parts.length - 1].replace(/\.html$/, "");
                    }
                    if (!slug) slug = meta.slug || "";

                    var hotspots = meta.hotspots || [];
                    var skus = [];
                    for (var h = 0; h < hotspots.length; h++) {
                        if (hotspots[h].sku && skus.indexOf(hotspots[h].sku) === -1) skus.push(hotspots[h].sku);
                    }

                    parsed.push({
                        slug: slug,
                        title: meta.title || (entry.title ? entry.title.$t : "") || "",
                        description: meta.description || "",
                        category: meta.category || "",
                        model: meta.model || "",
                        figureImage: meta.figureImage || meta.image || "",
                        thumbnail: meta.thumbnail || meta.figureImage || meta.image || "",
                        hotspots: hotspots,
                        hotspotCount: hotspots.length,
                        skuCount: skus.length,
                        skus: skus,
                        postUrl: alternateLink,
                        publishedat: meta.publishedat || ""
                    });
                } catch (e) { /* skip */ }
            }
            cache.data = parsed;
            cache.fetchedAt = now;
            return parsed;
        }
    } catch (e) {
        console.warn("fetchFigures failed:", e);
    }
    return [];
};

// ============================================
// 1. SHOP VIEW COMPONENT
// ============================================
window.shopData = function () {
    var defaultData = {
        search: "",
        activeCategory: "Semua",
        categories: ["Semua"],
        products: [],
        isLoadingProducts: true,
        loadError: false,
        currentPage: 1,
        perPage: 12
    };
    return {
        search: defaultData.search,
        activeCategory: defaultData.activeCategory,
        categories: defaultData.categories,
        products: defaultData.products,
        isLoadingProducts: defaultData.isLoadingProducts,
        loadError: defaultData.loadError,
        currentPage: defaultData.currentPage,
        perPage: defaultData.perPage,

        async init() {
            this.isLoadingProducts = true;
            try {
                this.products = await window.fetchProducts();
                this.loadError = false;

                var catSet = {};
                for (var ci = 0; ci < this.products.length; ci++) {
                    var pc = this.products[ci].category;
                    if (pc) catSet[pc] = true;
                }
                var cats = ["Semua"];
                for (var ck in catSet) cats.push(ck);
                this.categories = cats;
            } catch (e) {
                console.warn("Shop init failed:", e);
                this.loadError = true;
            } finally {
                this.isLoadingProducts = false;
            }
        },

        get filteredProducts() {
            var result = this.products;
            if (this.activeCategory !== "Semua") {
                result = result.filter(function (p) { return p.category === this.activeCategory; }.bind(this));
            }
            if (this.search.trim()) {
                var q = this.search.toLowerCase();
                result = result.filter(function (p) {
                    return p.name.toLowerCase().indexOf(q) !== -1 || p.category.toLowerCase().indexOf(q) !== -1;
                });
            }
            return result;
        },

        get paginatedProducts() {
            var start = (this.currentPage - 1) * this.perPage;
            return this.filteredProducts.slice(start, start + this.perPage);
        },

        get totalPages() {
            return Math.ceil(this.filteredProducts.length / this.perPage);
        },

        formatPrice: window.formatPrice
    };
};

// ============================================
// 2. PRODUCT VIEW COMPONENT
// ============================================
window.productViewData = function () {
    return {
        product: null,
        qty: 1,
        activeImage: 0,
        images: [],
        galleryOpen: false,

        init: function () {
            var self = this;
            var meta = window._lastResolvedMeta;
            if (meta) {
                self.product = meta;
                self.images = window.extractImages(meta);

                var needsFullData = (meta.stock === undefined || meta.stock === null || !meta.description);
                if (needsFullData && meta.slug) {
                    self.fetchFullMeta(meta.slug);
                }
            } else {
                self.product = { title: 'Produk Tidak Ditemukan', name: 'Produk Tidak Ditemukan', price: 0, description: 'Maaf, produk yang Anda cari tidak tersedia.' };
                self.images = ['??'];
            }

            if (window.app && typeof window.app.updateBreadcrumb === 'function') {
                window.app.updateBreadcrumb('product');
            }
        },

        fetchFullMeta: async function (slug) {
            var self = this;
            try {
                var entries = (await window.fetchProducts()) || [];
                var safeSlug = decodeURIComponent(slug).replace(/\s+/g, '-').toLowerCase();
                for (var i = 0; i < entries.length; i++) {
                    var entry = entries[i];
                    var entrySlug = (entry.slug || "").toLowerCase();
                    var entryId = (entry.id || "").toLowerCase();
                    var entryUrl = (entry.postUrl || "").toLowerCase();

                    if (entrySlug === safeSlug || entryId === safeSlug || (entryUrl && entryUrl.indexOf('/' + safeSlug + '.html') !== -1) || entry.slug === slug || entry.id === slug) {
                        Object.assign(self.product, entry);
                        self.images = window.extractImages(entry);
                        window._lastResolvedMeta = self.product;
                        break;
                    }
                }
            } catch (e) { console.warn('[productView] fetchFullMeta failed:', e); }
        },

        openGallery: function () {
            if (this.images.length === 0) return;
            this.galleryOpen = true;
            document.body.style.overflow = 'hidden';
        },

        closeGallery: function () {
            this.galleryOpen = false;
            document.body.style.overflow = '';
        },

        galleryPrev: function () {
            if (this.images.length > 1) {
                this.activeImage = (this.activeImage - 1 + this.images.length) % this.images.length;
            }
        },

        galleryNext: function () {
            if (this.images.length > 1) {
                this.activeImage = (this.activeImage + 1) % this.images.length;
            }
        },

        formatPrice: window.formatPrice,

        addToCart: function () {
            if (!this.product) return;

            // Ambil berat & satuan dari product
            const weight = Number(this.product.weight) || 0;
            const weightunit = this.product.weightunit || 'gram';

            this.$store.cart.add({
                id: this.product.id || this.product.slug || 'unknown',
                name: this.product.title || this.product.name,
                price: this.product.price || 0,
                sku: this.product.sku || '',
                imageurl: this.product.image || '',
                images: this.product.images || [],
                weight: weight,
                weightunit: weightunit
            }, this.qty);
            this.qty = 1;
        },

        get discountPct() {
            var cp = Number(this.product && this.product.compareatprice) || 0;
            var p = Number(this.product && this.product.price) || 0;
            return (cp > 0 && cp > p) ? Math.round((1 - p / cp) * 100) : 0;
        },

        get hasDiscount() { return this.discountPct > 0; },
        get stockLabel() { return (Number(this.product && this.product.stock) || 0) > 0 ? 'Tersedia' : 'Stok Habis'; },
        get stockColor() { return (Number(this.product && this.product.stock) || 0) > 0 ? 'text-green-600' : 'text-red-600'; }
    };
};

// ============================================
// 3. FIGURE VIEW DATA COMPONENT
// ============================================
window.figureViewData = function () {
    return {
        figure: null,
        hotspots: [],
        relatedFigures: [],
        activeHotspot: null,
        _closeTimer: null,
        viewMode: 'half',

        init: function () {
            var meta = window._lastResolvedMeta;
            if (meta && meta._type === 'figure') {
                this.figure = meta;
                this.hotspots = (meta.hotspots || []).map(function (h, i) {
                    h._index = i;
                    h._open = false;
                    // Fallback: hitung center untuk polygon jika x/y belum ada
                    if (h.type === 'polygon' && Array.isArray(h.points) && h.points.length > 0 && (h.x === undefined || h.x === null)) {
                        var sx = 0, sy = 0;
                        h.points.forEach(function (p) { sx += p.x; sy += p.y; });
                        h.x = Math.round((sx / h.points.length) * 100) / 100;
                        h.y = Math.round((sy / h.points.length) * 100) / 100;
                    }
                    return h;
                });
                this.resolveHotspotProducts();
                this.loadRelatedFigures();
            } else {
                this.figure = meta || { title: 'Figure Tidak Ditemukan' };
                this.hotspots = [];
            }
            if (window.app && typeof window.app.updateBreadcrumb === 'function') {
                window.app.updateBreadcrumb('figure');
            }
        },

        resolveHotspotProducts: async function () {
            try {
                var entries = (await window.fetchProducts()) || [];
                var skuMap = {};
                entries.forEach(function (p) { if (p.sku) skuMap[p.sku] = p; });
                var figImage = (this.figure && this.figure.figureImage) || '';
                this.hotspots.forEach(function (h) {
                    if (h.sku && skuMap[h.sku]) {
                        var p = skuMap[h.sku];
                        h._product = p;
                        h._imageUrl = p.image || figImage;
                        h._price = p.price;
                        h._slug = p.slug;
                    } else {
                        h._imageUrl = figImage;
                    }
                });
            } catch (e) {
                console.warn('[figureView] resolveHotspotProducts failed:', e);
            }
        },

        loadRelatedFigures: async function () {
            var currentModel = this.figure && this.figure.model;
            var currentSlug = this.figure && this.figure.slug;
            if (!currentModel) return;
            try {
                var allFigures = (await window.fetchFigures()) || [];
                this.relatedFigures = allFigures.filter(function (f) {
                    return f.model === currentModel;
                }).sort(function (a, b) {
                    return (a.title || '').localeCompare(b.title || '', undefined, { numeric: true, sensitivity: 'base' });
                });
            } catch (e) {
                console.warn('[figureView] loadRelatedFigures failed:', e);
            }
        },

        navigateToFigure: function (f) {
            if (!f || !f.slug) return;
            var dp = window.extractDateParams({ publishedat: f.publishedat }) || {};
            window.navigate('figure', {
                slug: f.slug,
                year: dp.year || '',
                month: dp.month || '',
                meta: {
                    slug: f.slug,
                    title: f.title,
                    description: f.description,
                    model: f.model || '',
                    category: f.category || '',
                    figureImage: f.figureImage,
                    hotspots: f.hotspots || [],
                    publishedat: f.publishedat || '',
                    postUrl: f.postUrl || '',
                    _type: 'figure'
                }
            });
        },

        toggleHotspot: function (h) {
            this.hotspots.forEach(function (hp) { hp._open = false; });
            if (this.activeHotspot && this.activeHotspot.id === h.id) {
                this.activeHotspot = null;
            } else {
                h._open = true;
                this.activeHotspot = h;
            }
        },

        closeHotspot: function () {
            this.hotspots.forEach(function (hp) { hp._open = false; });
            this.activeHotspot = null;
        },

        openHotspotHover: function (h) {
            if (this._closeTimer) {
                clearTimeout(this._closeTimer);
                this._closeTimer = null;
            }
            this.hotspots.forEach(function (hp) { hp._open = false; });
            h._open = true;
            this.activeHotspot = h;
        },

        scheduleCloseHotspot: function (h) {
            var self = this;
            this._closeTimer = setTimeout(function () {
                h._open = false;
                if (self.activeHotspot && self.activeHotspot.id === h.id) {
                    self.activeHotspot = null;
                }
                self._closeTimer = null;
            }, 250);
        },

        cancelCloseHotspot: function () {
            if (this._closeTimer) {
                clearTimeout(this._closeTimer);
                this._closeTimer = null;
            }
        },

        scrollToTableRow: function (h) {
            if (this.isMobile) {
                this.toggleHotspot(h);
                return;
            }

            this.openHotspotHover(h);

            var self = this;
            setTimeout(function () {
                var row = document.getElementById('comp-row-' + h.id);
                if (row) {
                    row.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    self._highlightRow(h.id);
                }
            }, 120);
        },

        _highlightRow: function (id) {
            var row = document.getElementById('comp-row-' + id);
            if (!row) return;
            row.classList.add('row-highlight');
            setTimeout(function () {
                row.classList.remove('row-highlight');
            }, 1400);
        },

        scrollToHotspot: function (h) {
            var wasActive = this.activeHotspot && this.activeHotspot.id === h.id;
            this.toggleHotspot(h);
            if (wasActive) return;

            var self = this;
            setTimeout(function () {
                var el = document.getElementById('hotspot-' + h.id);
                if (el) {
                    el.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });
                    self._highlightHotspot(h.id);
                }
            }, 120);
        },

        _highlightHotspot: function (id) {
            var el = document.getElementById('hotspot-' + id);
            if (!el) return;
            var dot = el.querySelector('span:nth-child(2)');
            if (!dot) return;
            dot.classList.add('hotspot-highlight');
            setTimeout(function () {
                dot.classList.remove('hotspot-highlight');
            }, 1400);
        },

        goToProduct: function (h) {
            if (h._slug && h._product) {
                var dp = window.extractDateParams({ publishedat: h._product.publishedat });
                window.navigate('product', {
                    slug: h._slug,
                    year: dp.year,
                    month: dp.month,
                    meta: h._product
                });
            }
        },

        cycleViewMode: function () {
            this.viewMode = this.viewMode === 'fit' ? 'half' : 'fit';
        },

        get viewModeIcon() {
            return this.viewMode === 'fit' ? 'minimize' : 'maximize';
        },

        get viewModeTitle() {
            return this.viewMode === 'fit' ? 'Perkecil (50%)' : 'Kembalikan ke Penuh';
        },

        get cardStyle() {
            var base = 'left:50%;bottom:calc(100% + 8px);';
            if (this.viewMode === 'half') {
                return base + 'transform:translateX(-50%) scale(0.75);transform-origin:center bottom;';
            }
            return base + 'transform:translateX(-50%);';
        },

        get transformStyle() {
            return '';
        },
        get isZoomed() {
            return false;
        }
    };
};

