// ============================================
// 4. RELATED PRODUCTS COMPONENT
// ============================================
window.relatedProductsData = function () {
    return {
        relatedProducts: [],
        isLoadingRelated: true,

        async init() {
            var meta = window._lastResolvedMeta;
            if (!meta || !meta.category) {
                this.isLoadingRelated = false;
                return;
            }

            var currentSlug = meta.slug || meta.id || '';
            try {
                var entries = await window.fetchProducts();
                var related = [];

                for (var i = 0; i < entries.length; i++) {
                    var p = entries[i];
                    if ((p.slug === currentSlug || p.id === currentSlug) || p.category !== meta.category) continue;
                    related.push({
                        id: p.id,
                        name: p.name,
                        slug: p.slug,
                        price: p.price,
                        category: p.category,
                        image: p.image,
                        publishedat: p.publishedat
                    });
                }
                this.relatedProducts = related.slice(0, 4);
            } catch (e) {
                console.warn('Related fetch failed:', e);
            } finally {
                this.isLoadingRelated = false;
            }
        },

        formatPrice: window.formatPrice
    };
};

// ============================================
// FIGURE SEARCH/DATA COMPONENT
// ============================================
window.figureSearchData = function () {
    return {
        allResults: [],
        filteredResults: [],
        categories: [],
        selectedCategory: '',
        vehicleModels: [],
        selectedModel: '',
        searchQuery: '',
        isLoading: true,
        currentPage: 1,
        perPage: 10,

        get paginatedResults() {
            var start = (this.currentPage - 1) * this.perPage;
            return this.filteredResults.slice(start, start + this.perPage);
        },

        get totalPages() {
            return Math.ceil(this.filteredResults.length / this.perPage) || 1;
        },

        goToPage(page) {
            if (page < 1 || page > this.totalPages) return;
            this.currentPage = page;
        },

        async init() {
            this.isLoading = true;
            try {
                var figures = await window.fetchFigures();
                var models = [];
                var cats = [];
                for (var i = 0; i < figures.length; i++) {
                    if (figures[i].model && models.indexOf(figures[i].model) === -1) {
                        models.push(figures[i].model);
                    }
                    if (figures[i].category && cats.indexOf(figures[i].category) === -1) {
                        cats.push(figures[i].category);
                    }
                }
                models.sort();
                cats.sort();
                this.vehicleModels = models;
                this.categories = cats;
                this.allResults = figures;
                this.filteredResults = figures;
            } catch (e) {
                console.warn('Figure search init failed:', e);
            }
            this.isLoading = false;
        },

        filterResults() {
            var q = (this.searchQuery || '').toLowerCase().trim();
            var model = this.selectedModel || '';
            var category = this.selectedCategory || '';
            var results = this.allResults;

            if (category) {
                results = results.filter(function (item) { return item.category === category; });
            }

            if (model) {
                results = results.filter(function (item) { return item.model === model; });
            }

            if (q) {
                results = results.filter(function (item) {
                    if ((item.title || '').toLowerCase().indexOf(q) !== -1) return true;
                    if ((item.description || '').toLowerCase().indexOf(q) !== -1) return true;
                    if ((item.slug || '').toLowerCase().indexOf(q) !== -1) return true;
                    for (var s = 0; s < (item.skus || []).length; s++) {
                        if (item.skus[s].toLowerCase().indexOf(q) !== -1) return true;
                    }
                    return false;
                });
            }

            this.filteredResults = results;
            this.currentPage = 1;
        },

        openFigure(item) {
            if (!item || !item.slug) return;
            var dp = window.extractDateParams({ publishedat: item.publishedat }) || {};
            window.navigate('figure', {
                slug: item.slug,
                year: dp.year || '',
                month: dp.month || '',
                meta: {
                    slug: item.slug,
                    title: item.title,
                    description: item.description,
                    model: item.model || '',
                    category: item.category || '',
                    figureImage: item.figureImage,
                    hotspots: item.hotspots || [],
                    publishedat: item.publishedat || '',
                    postUrl: item.postUrl || '',
                    _type: 'figure'
                }
            });
        }
    };
};

// ============================================
// 5. POST LIST COMPONENT
// ============================================

window._postCache = window._postCache || { data: null, fetchedAt: 0, ttl: 5 * 60 * 1000 };

window.fetchPosts = async function () {
    var cache = window._postCache;
    var now = Date.now();
    if (cache.data && (now - cache.fetchedAt) < cache.ttl) return cache.data;

    try {
        var res = await fetch("/feeds/posts/default?alt=json&maxResults=500");
        if (!res.ok) throw new Error("Fetch failed");
        var json = await res.json();

        if (json.feed && json.feed.entry) {
            var parsed = [];
            for (var idx = 0; idx < json.feed.entry.length; idx++) {
                try {
                    var entry = json.feed.entry[idx];
                    var content = entry.content && entry.content.$t ? entry.content.$t : "";

                    // Skip Product & Figure posts
                    var isSpecial = false;
                    if (entry.category) {
                        for (var c = 0; c < entry.category.length; c++) {
                            var term = (entry.category[c].term || "").toLowerCase();
                            if (term === "product" || term === "figure") { isSpecial = true; break; }
                        }
                    }
                    if (isSpecial) continue;

                    var alternateLink = "";
                    if (entry.link) {
                        for (var k = 0; k < entry.link.length; k++) {
                            if (entry.link[k].rel === "alternate") {
                                alternateLink = entry.link[k].href;
                                break;
                            }
                        }
                    }

                    var slug = "";
                    if (alternateLink) {
                        var parts = alternateLink.replace(/\/$/, "").split("/");
                        slug = parts[parts.length - 1].replace(/\.html$/, "");
                    }

                    // Extract meta if available
                    var meta = window.parseEzyMeta(content);

                    // Extract date
                    var published = "";
                    if (entry.published && entry.published.$t) {
                        published = entry.published.$t;
                    } else if (entry.updated && entry.updated.$t) {
                        published = entry.updated.$t;
                    }

                    // Labels
                    var labels = [];
                    if (entry.category) {
                        for (var lc = 0; lc < entry.category.length; lc++) {
                            var lt = entry.category[lc].term || "";
                            if (lt && lt.toLowerCase() !== "product" && lt.toLowerCase() !== "figure") {
                                labels.push(lt);
                            }
                        }
                    }

                    // Extract body text for snippet
                    var bodyText = "";
                    if (content) {
                        var tmpDoc = new DOMParser().parseFromString(content, "text/html");
                        bodyText = (tmpDoc.body.textContent || "").trim();
                    }

                    // Featured image
                    var featuredImage = "";
                    if (meta && meta.image) {
                        featuredImage = meta.image;
                    } else if (entry.media$thumbnail) {
                        featuredImage = entry.media$thumbnail.url || "";
                    }

                    parsed.push({
                        slug: slug,
                        title: entry.title ? entry.title.$t : "",
                        publishedat: published,
                        labels: labels,
                        category: labels.length > 0 ? labels[0] : "",
                        image: featuredImage,
                        snippet: bodyText.length > 160 ? bodyText.substring(0, 160) + "..." : bodyText,
                        postUrl: alternateLink,
                        _type: "post"
                    });
                } catch (e) { /* skip */ }
            }

            // Sort by date descending
            parsed.sort(function (a, b) {
                return new Date(b.publishedat) - new Date(a.publishedat);
            });

            cache.data = parsed;
            cache.fetchedAt = now;
            return parsed;
        }
    } catch (e) {
        console.warn("fetchPosts failed:", e);
    }
    return [];
};

window.postListData = function () {
    return {
        posts: [],
        filteredPosts: [],
        categories: [],
        activeCategory: "Semua",
        search: "",
        isLoading: true,
        loadError: false,
        currentPage: 1,
        perPage: 9,
        routeYear: "",
        routeMonth: "",

        get paginatedPosts() {
            var start = (this.currentPage - 1) * this.perPage;
            return this.filteredPosts.slice(start, start + this.perPage);
        },

        get totalPages() {
            return Math.ceil(this.filteredPosts.length / this.perPage);
        },

        get monthLabel() {
            if (!this.routeYear) return "";
            var monthNames = ["", "Januari", "Februari", "Maret", "April", "Mei", "Juni",
                "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
            var m = parseInt(this.routeMonth) || 0;
            return m ? monthNames[m] + " " + this.routeYear : this.routeYear;
        },

        formatDate: function (dateStr) {
            if (!dateStr) return "";
            try {
                var d = new Date(dateStr);
                if (isNaN(d.getTime())) return "";
                var day = d.getDate();
                var monthNames = ["Jan", "Feb", "Mar", "Apr", "Mei", "Jun",
                    "Jul", "Agu", "Sep", "Okt", "Nov", "Des"];
                return day + " " + monthNames[d.getMonth()] + " " + d.getFullYear();
            } catch (e) { return ""; }
        },

        async init() {
            this.isLoading = true;

            // Parse route params from app
            if (window.app && window.app.params) {
                this.routeYear = window.app.params.year || "";
                this.routeMonth = window.app.params.month || "";
            }

            try {
                var allPosts = await window.fetchPosts();
                this.posts = allPosts;
                this.loadError = false;

                // Build categories
                var catSet = {};
                for (var i = 0; i < allPosts.length; i++) {
                    var cat = allPosts[i].category;
                    if (cat) catSet[cat] = true;
                }
                var cats = ["Semua"];
                for (var ck in catSet) cats.push(ck);
                this.categories = cats;

                this.applyFilters();
            } catch (e) {
                console.warn("Post list init failed:", e);
                this.loadError = true;
            } finally {
                this.isLoading = false;
            }
        },

        applyFilters() {
            var result = this.posts;

            // Filter by month if route has year/month
            if (this.routeYear && this.routeMonth) {
                var ry = parseInt(this.routeYear);
                var rm = parseInt(this.routeMonth);
                result = result.filter(function (p) {
                    if (!p.publishedat) return false;
                    try {
                        var d = new Date(p.publishedat);
                        return d.getFullYear() === ry && (d.getMonth() + 1) === rm;
                    } catch (e) { return false; }
                });
            } else if (this.routeYear) {
                var ry2 = parseInt(this.routeYear);
                result = result.filter(function (p) {
                    if (!p.publishedat) return false;
                    try { return new Date(p.publishedat).getFullYear() === ry2; }
                    catch (e) { return false; }
                });
            }

            // Category filter
            if (this.activeCategory !== "Semua") {
                var cat = this.activeCategory;
                result = result.filter(function (p) { return p.category === cat; });
            }

            // Search filter
            if (this.search.trim()) {
                var q = this.search.toLowerCase();
                result = result.filter(function (p) {
                    return (p.title || "").toLowerCase().indexOf(q) !== -1 ||
                        (p.snippet || "").toLowerCase().indexOf(q) !== -1 ||
                        (p.category || "").toLowerCase().indexOf(q) !== -1;
                });
            }

            this.filteredPosts = result;
            this.currentPage = 1;
        },

        openPost: function (post) {
            if (!post || !post.slug) return;
            var dp = window.extractDateParams({ publishedat: post.publishedat }) || {};
            window.navigate('post', {
                slug: post.slug,
                year: dp.year || '',
                month: dp.month || '',
                meta: {
                    slug: post.slug,
                    title: post.title,
                    image: post.image || '',
                    snippet: post.snippet || '',
                    publishedat: post.publishedat || '',
                    labels: post.labels || [],
                    category: post.category || '',
                    postUrl: post.postUrl || '',
                    _type: 'post'
                }
            });
        }
    };
};

