// 6. POST VIEW COMPONENT
// ============================================
window.postViewData = function () {
    return {
        post: null,
        relatedPosts: [],
        isLoading: true,

        init: function () {
            var self = this;
            var meta = window._lastResolvedMeta;

            if (meta && (meta._type === 'post' || meta._type === 'blogger')) {
                self.post = meta;
                self.loadFullContent(meta);
            } else if (meta && meta.slug) {
                // Fallback: try to resolve from feed
                self.post = meta;
                self.loadFullContent(meta);
            } else {
                self.post = {
                    title: 'Artikel Tidak Ditemukan',
                    snippet: 'Maaf, artikel yang Anda cari tidak tersedia.',
                    image: '',
                    publishedat: '',
                    labels: []
                };
            }

            self.loadRelatedPosts();

            if (window.app && typeof window.app.updateBreadcrumb === 'function') {
                window.app.updateBreadcrumb('post');
            }
        },

        loadFullContent: async function (meta) {
            var self = this;
            if (!meta || !meta.slug) return;

            try {
                var entries = await window.fetchPosts();
                var safeSlug = decodeURIComponent(meta.slug).replace(/\s+/g, '-').toLowerCase();

                for (var i = 0; i < entries.length; i++) {
                    var entry = entries[i];
                    var entrySlug = (entry.slug || "").toLowerCase();

                    if (entrySlug === safeSlug || entry.slug === meta.slug || entry.id === meta.slug) {
                        // Merge full data
                        if (entry.title && !self.post.title) self.post.title = entry.title;
                        if (entry.snippet) self.post.snippet = entry.snippet;
                        if (entry.image) self.post.image = entry.image;
                        if (entry.publishedat) self.post.publishedat = entry.publishedat;
                        if (entry.labels && entry.labels.length) self.post.labels = entry.labels;
                        if (entry.category) self.post.category = entry.category;
                        self.post.postUrl = entry.postUrl || '';

                        // Try to get body content from Blogger feed
                        var res2 = await fetch("/feeds/posts/default/-/" + encodeURIComponent(entry.category || "undefined") + "?alt=json&max-results=500");
                        if (res2.ok) {
                            var json2 = await res2.json();
                            if (json2.feed && json2.feed.entry) {
                                for (var j = 0; j < json2.feed.entry.length; j++) {
                                    var e2 = json2.feed.entry[j];
                                    var s2 = "";
                                    if (e2.link) {
                                        for (var kl = 0; kl < e2.link.length; kl++) {
                                            if (e2.link[kl].rel === "alternate") {
                                                s2 = e2.link[kl].href.replace(/\/$/, "").split("/").pop().replace(/\.html$/, "");
                                                break;
                                            }
                                        }
                                    }
                                    if (s2 === safeSlug || s2 === entry.slug) {
                                        var rawContent = e2.content && e2.content.$t ? e2.content.$t : "";
                                        if (rawContent) {
                                            var tmpDoc = new DOMParser().parseFromString(rawContent, "text/html");
                                            var ezyMetaEl = tmpDoc.querySelector(".ezy-meta");
                                            if (ezyMetaEl) ezyMetaEl.remove();
                                            self.post.body = tmpDoc.body.innerHTML || tmpDoc.body.textContent || "";
                                        }
                                        if (e2.media$thumbnail && !self.post.image) {
                                            self.post.image = e2.media$thumbnail.url || "";
                                        }
                                        break;
                                    }
                                }
                            }
                        }

                        window._lastResolvedMeta = self.post;
                        break;
                    }
                }
            } catch (e) {
                console.warn('[postView] loadFullContent failed:', e);
            }
        },

        loadRelatedPosts: async function () {
            var self = this;
            var currentSlug = self.post && self.post.slug;
            var currentCategory = self.post && self.post.category;

            try {
                var allPosts = await window.fetchPosts();
                self.relatedPosts = allPosts.filter(function (p) {
                    if (p.slug === currentSlug) return false;
                    if (currentCategory && p.category === currentCategory) return true;
                    return false;
                }).slice(0, 4);
            } catch (e) {
                console.warn('Related posts fetch failed:', e);
            }
        },

        formatDate: function (dateStr) {
            if (!dateStr) return "";
            try {
                var d = new Date(dateStr);
                if (isNaN(d.getTime())) return "";
                var day = d.getDate();
                var monthNames = ["Januari", "Februari", "Maret", "April", "Mei", "Juni",
                    "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
                return day + " " + monthNames[d.getMonth()] + " " + d.getFullYear();
            } catch (e) { return ""; }
        },

        formatShortDate: function (dateStr) {
            if (!dateStr) return "";
            try {
                var d = new Date(dateStr);
                if (isNaN(d.getTime())) return "";
                var day = d.getDate();
                var monthNames = ["Jan", "Feb", "Mar", "Apr", "Mei", "Jun",
                    "Jul", "Agu", "Sep", "Okt", "Nov", "Des"];
                return day + " " + monthNames[d.getMonth()] + " " + d.getFullYear();
            } catch (e) { return ""; }
        },

        navigateToPost: function (post) {
            if (!post || !post.slug) return;
            var dp = window.extractDateParams({ publishedat: post.publishedat }) || {};
            window.navigate('post', {
                slug: post.slug,
                year: dp.year || '',
                month: dp.month || '',
                meta: {
                    slug: post.slug,
                    title: post.title,
                    image: post.image || '',
                    snippet: post.snippet || '',
                    publishedat: post.publishedat || '',
                    labels: post.labels || [],
                    category: post.category || '',
                    postUrl: post.postUrl || '',
                    _type: 'post'
                }
            });
        }
    };
};

