window.ecommercePayment = function () {
    return {
        step: 1,
        form: {
            name: '',
            email: '',
            phone: '',
            address: '',
            city: '',
            postalCode: '',
            notes: '',
            paymentMethod: 'transfer'
        },
        shippingCost: 0,

        nextStep() {
            if (this.step === 1 && this.$store.cart.items.length === 0) return;
            if (this.step === 2 && !this.validateShippingForm()) return;
            if (this.step < 4) this.step++;
        },

        prevStep() {
            if (this.step > 1) this.step--;
        },

        validateShippingForm() {
            return !!(
                this.form.name &&
                this.form.email &&
                this.form.phone &&
                this.form.address &&
                this.form.city
            );
        },

        submitOrder() {
            // Simulasi submit order
            alert('Pesanan dikirim! Nomor pesanan: INV-' + Date.now().toString().slice(-6));
            this.$store.cart.clear();
            this.step = 4;
        },

        get grandTotal() {
            return this.$store.cart.total + this.shippingCost;
        }
    };
};

